    var qreg=f*(1-cfg.unreg),qun=f*cfg.unreg;
    if(unregBase)qun*=(P+PATM)/(unregBase+PATM);         // artificial demand ตามความดันสัมบูรณ์
    var qd=qreg+qun,qs=0,W=0,j,u,x,Pl;
