        if(best>=0&&best!==curMask&&(bestKW<curKW*0.97||curKW>=1e15)){for(j=0;j<nB;j++){x=st[order[j]];var want=!!(best&(1<<j));if(want&&x.s!=='load'){x.s='load';x.c=1;x.cyc++;}else if(!want&&x.s==='load'){x.s=(units[order[j]].type==='onoff')?'off':'unload';x.tU=0;}}tChg=t;}
