const TE_P0=101.325;                                                  // kPa
const wFromRH=(T,RH)=>TE_PSY.W_rh(T,RH/100,TE_P0);
function wFromWB(T,Twb){return TE_PSY.W_wb(T,Twb,TE_P0);}
const fmt=(v,d)=>v.toLocaleString('en-US',{maximumFractionDigits:d===undefined?0:d});
const kW2BTU=kw=>kw*3412.14, kW2TR=kw=>kw/3.517;
const SPLIT_SIZES=[9,12,13,18,24,25,30,36,40,48,60];
function splitSize(btuh){
  const kb=btuh/1000;
  for(const s of SPLIT_SIZES)if(s>=kb)return s;
  return null;
}
function roomReco(r){
  const btuh=kW2BTU(r.total),tr=kW2TR(r.total);
  let rec=[];
  if(r.cls==='critical'){
    if(r.type==='dc'){
      rec.push('<b>Precision air (CRAH น้ำเย็น หรือ CRAC DX)</b> ขนาดรวม ≥ '+fmt(r.total,1)+' kW sensible — จัดรูปแบบ <b>N+1</b> (เช่น '+Math.ceil(r.total/30)+'+1 เครื่อง × 30 kW)');
      rec.push('จัด hot/cold aisle, ตั้ง supply ตาม ASHRAE TC9.9 (แนะนำ 18–27 °C @ inlet), ห้ามใช้แอร์บ้านเป็นระบบหลัก');
      if(r.total>150)rec.push('โหลดระดับนี้ควรพิจารณา chilled water + CRAH หรือ InRow cooling พร้อม chiller N+1');
    }else if(r.type==='server'){
      rec.push('<b>Precision air ขนาดเล็ก หรือ split inverter คู่ (duty/standby สลับกัน)</b> ขนาดเครื่องละ ≥ '+fmt(btuh)+' BTU/hr — ทำงาน 24 ชม. ต้องมีสำรอง 100%');
      rec.push('ติด alarm อุณหภูมิสูง + สลับเครื่องอัตโนมัติ (sequencer)');
    }else{
      rec.push('<b>Control Room:</b> split/ducted inverter <b>2 ชุด duty/standby</b> ('+fmt(btuh)+' BTU/hr ต่อชุด) หรือต่อจากระบบน้ำเย็นกลางพร้อม FCU สำรอง — งาน 24 ชม.');
    }
  }else if(r.cls==='electrical'){
    rec.push('<b>ห้องไฟฟ้า:</b> ระบายความร้อน '+fmt(r.total,1)+' kW — พิจารณา<b>พัดลมระบายอากาศก่อน</b> (ยอมรับอุณหภูมิ ≤ 35–40 °C ได้ถ้าไม่มีอุปกรณ์อิเล็กทรอนิกส์ไว) ถ้ามี VSD/PLC/UPS ให้ใช้ split inverter '+(splitSize(btuh)?splitSize(btuh)+',000 BTU/hr':'ขนาด '+fmt(btuh)+' BTU/hr')+' ×2 (duty/standby)');
    if(r.type==='ups')rec.push('ห้อง Battery VRLA: คุม 25±2 °C — อายุแบตลดครึ่งทุก ๆ +8–10 K · ระวังการระบาย H₂');
  }else{
    const s=splitSize(btuh);
    if(btuh<=60000&&s){
      rec.push('<b>Split type inverter '+s+',000 BTU/hr</b> (โหลดจริง '+fmt(btuh)+' BTU/hr) — เลือกเบอร์ 5 ★★★, SEER ≥ 18');
      if(r.shr<0.7)rec.push('SHR ต่ำ ('+r.shr.toFixed(2)+') คนแน่น/อากาศระบายมาก — ระวังเครื่อง oversize จะคุมความชื้นไม่อยู่ เลือกเครื่องที่ latent capacity เพียงพอ หรือลด oversize');
    }else if(tr<=25){
      rec.push('<b>Cassette/Ducted split หลายชุด หรือ VRF</b> ('+fmt(tr,1)+' TR) — VRF เหมาะเมื่อหลายห้องใช้พร้อมกันไม่หมด (diversity)');
    }else{
      rec.push('โหลด '+fmt(tr,1)+' TR — ระดับนี้ควรเข้า<b>ระบบน้ำเย็นรวม (chiller + AHU/FCU)</b> ดูคำแนะนำระดับ plant ด้านล่าง');
    }
    if(r.type==='rest'||r.type==='lab')rec.push('มี exhaust มาก — คิด makeup air unit แยก และตรวจสมดุลอากาศ');
  }
  return rec;
}
