function fgModel(fuelKey, o2pct){
  const c=FG_COMP[fuelKey]||FG_COMP.custom; let O2=0,CO2=0,H2O=0,N2=0,SO2=0;
  if(c.v){ const S={CH4:[2,1,2],C2H6:[3.5,2,3],C3H8:[5,3,4],C4H10:[6.5,4,5],H2:[0.5,0,1]};
    Object.keys(c.v).forEach(k=>{const f=c.v[k]/100; if(S[k]){O2+=f*S[k][0];CO2+=f*S[k][1];H2O+=f*S[k][2];} else if(k==='CO2')CO2+=f; else if(k==='N2')N2+=f;}); }
  else { const g=x=>(c.m[x]||0)/100, V=22.414;
    O2=V*(g('C')/12.011+g('H')/4.032+g('S')/32.06-g('O')/31.998); CO2=V*g('C')/12.011; H2O=V*(g('H')/2.016+g('W')/18.015); SO2=V*g('S')/32.06; N2=V*g('N')/28.013; }
  const Va0=O2/0.21, o=Math.max(0,o2pct)/100, D0=CO2+SO2+N2;
  const beta=o*(D0+0.79*Va0)/(Va0*(0.21-o));            // O₂ วัดแบบแห้ง: 0.21βVa0 = o·(D0 + 0.79αVa0 + 0.21βVa0)
  const alpha=1+beta, nO2=0.21*beta*Va0, nN2=N2+0.79*alpha*Va0, Vwet=CO2+SO2+H2O+nN2+nO2;
  return {Va0, alpha, ea:beta*100, Vwet, x:{CO2:CO2/Vwet,SO2:SO2/Vwet,H2O:H2O/Vwet,N2:nN2/Vwet,O2:nO2/Vwet}};
}
function fgCpMix(x,t1,t2){
  const H=(c,T)=>c[0]*T+c[1]*T*T/2+c[2]*T*T*T/3+c[3]*T*T*T*T/4;
  let a=Math.min(t1,t2)+273.15, b=Math.max(t1,t2)+273.15; if(b-a<1) b=a+1;
  let s=0; Object.keys(x).forEach(k=>{ if(FG_CPC[k]) s+=x[k]*(H(FG_CPC[k],b)-H(FG_CPC[k],a))/(b-a); });
  return s/22.414;
}
