function robustLMTD(tHot_in, tHot_out, tCold_in, tCold_out) {
  // Counter-flow convention: hot enters where cold leaves
  const dt1 = tHot_in  - tCold_out;   // hot inlet end
  const dt2 = tHot_out - tCold_in;    // hot outlet end

  // Temperature cross / infeasible (one end has hot ≤ cold)
  if (dt1 <= 0 || dt2 <= 0) {
    return { lmtd: NaN, method: 'infeasible', valid: false, dt1, dt2 };
  }

  const ratio = dt1 / dt2;
  // If ΔT1 and ΔT2 are within 1% of each other, ln term is numerically unstable.
  // AMTD differs from LMTD by <0.1% in this range, so use AMTD safely.
  if (Math.abs(ratio - 1) < 0.01) {
    return { lmtd: (dt1 + dt2) / 2, method: 'AMTD', valid: true, dt1, dt2 };
  }

  const lmtd = (dt1 - dt2) / Math.log(ratio);
  if (!isFinite(lmtd) || lmtd <= 0) {
    // Last-resort guard
    return { lmtd: (dt1 + dt2) / 2, method: 'AMTD', valid: true, dt1, dt2 };
  }
  return { lmtd, method: 'LMTD', valid: true, dt1, dt2 };
}
function cpWater(T_C) {
  const T = (T_C === undefined || T_C === null || !isFinite(T_C)) ? 25 : T_C;
  const t = Math.max(0, Math.min(180, T));   // clamp to fit's valid range
  const cp = 4.200671 - 9.732100e-4 * t + 1.129510e-5 * t * t;
  return Math.round(cp * 10000) / 10000;
}
function calcHXArea(q_kW, lmtd, U_mid) {
  // A = Q / (U × LMTD)   [m²]
  // Q in W, U in W/(m²·K), LMTD in K
  if (!lmtd || lmtd <= 0 || !U_mid || U_mid <= 0) return null;
  return (q_kW * 1000) / (U_mid * lmtd);
}
